-- Accent/case-insensitive product search (MySQL utf8mb4_unicode_ci used to match 'Rim' to 'Řím', SQLite LIKE only folds ASCII case).
-- search_text = folded title+description+country+destination+place+type_raw, maintained by triggers so importers need no change.
-- Query side folds the term the same way (src/lib/products/search-text.ts foldText).
ALTER TABLE products ADD COLUMN search_text TEXT NOT NULL DEFAULT '';

